import React, { useState, useEffect } from "react";
import productService from "../../services/productService";

const ProductList = () => {
  const [products, setProducts] = useState([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    const fetchProducts = async () => {
      try {
        const response = await productService.getAllProducts();
        // Axios thường bọc dữ liệu trong response.data
        setProducts(response.data || response);
      } catch (error) {
        console.error("Lỗi khi tải danh sách sản phẩm:", error);
      } finally {
        setLoading(false);
      }
    };

    fetchProducts();
  }, []);

  // Giao diện khi đang đợi API tải dữ liệu (Loading Skeleton)
  if (loading) {
    return (
      <div className="row g-4">
        {[1, 2, 3, 4].map((n) => (
          <div className="col-12 col-sm-6 col-md-4 col-lg-3" key={n}>
            <div className="card border-0 p-3 shadow-sm placeholder-glow" style={{ height: "350px", borderRadius: "12px" }}>
              <div className="placeholder bg-secondary opacity-10 rounded-3 w-100 h-50 mb-3"></div>
              <div className="placeholder bg-secondary opacity-10 w-75 mb-2"></div>
              <div className="placeholder bg-secondary opacity-10 w-50"></div>
            </div>
          </div>
        ))}
      </div>
    );
  }

  // Trường hợp API chạy thành công nhưng không có sản phẩm nào
  if (products.length === 0) {
    return <p className="text-center text-muted my-5">Hiện chưa có sản phẩm nào được hiển thị.</p>;
  }

  return (
    <div className="row g-4">
      {products.map((product) => (
        <div className="col-12 col-sm-6 col-md-4 col-lg-3" key={product.id}>
          <div className="modern-product-card border-0 rounded-3 shadow-sm bg-white overflow-hidden h-100 d-flex flex-column justify-content-between position-relative">
            
            {/* 1. Khung chứa ảnh sản phẩm */}
            <div 
              className="product-img-wrapper p-4 d-flex align-items-center justify-content-center position-relative overflow-hidden" 
              style={{ height: "220px", backgroundColor: "#f8f9fa" }}
            >
              <img 
                /* ĐÃ SỬA: Đổi từ product.image sang product.imageUrl khớp với API */
                src={product.imageUrl || "https://placehold.co/300x300?text=No+Image"} 
                className="img-fluid object-fit-contain h-100 product-img" 
                alt={product.name} 
                onError={(e) => { e.target.src = "https://placehold.co/300x300?text=No+Image" }}
              />
            </div>
            
            {/* 2. Phần thông tin chi tiết sản phẩm */}
            <div className="p-3 text-center d-flex flex-column flex-grow-1 justify-content-between">
              <div>
                <h5 className="fs-6 fw-semibold text-dark text-truncate mb-1" title={product.name}>
                  {product.name}
                </h5>
                <p className="text-muted small text-truncate mb-2" style={{ fontSize: "0.8rem" }}>
                  {product.description || "Thiết kế thông minh, hiện đại"}
                </p>
              </div>
              
              <div>
                {/* Định dạng giá tiền VNĐ */}
                <p className="text-danger fw-bold mb-3 fs-6">
                  {typeof product.price === 'number' 
                    ? product.price.toLocaleString('vi-VN', { style: 'currency', currency: 'VND' }) 
                    : `${product.price}`}
                </p>
                
                {/* Nút thêm vào giỏ */}
                <button className="btn btn-outline-dark btn-sm w-100 rounded-pill px-4 btn-add-cart">
                  Thêm vào giỏ
                </button>
              </div>
            </div>

          </div>
        </div>
      ))}
    </div>
  );
};

export default ProductList;
